<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,PerformanceMetric,SyncRun,RawProviderPayload};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
final class CanonicalIntegrityAuditTest extends TestCase {
 use DatabaseTransactions;
 private function fixture():array{$u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Synthetic','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Synthetic','currency'=>'USD']);return[$u,$a,$c];}
 private function metric($a,$c,array $overrides=[]){return PerformanceMetric::create(array_merge(['connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'provider'=>'meta','date'=>'2026-11-01','currency'=>'USD','spend'=>10,'impressions'=>100,'clicks'=>2,'conversions'=>1,'conversion_value'=>20],$overrides));}
 private function url($a):string{return '/api/v1/ad-accounts/'.$a->id.'/canonical-integrity?start_date=2026-11-01&end_date=2026-11-02';}
 public function test_scope_empty_and_date_guards():void{[$u,$a]=$this->fixture();$url=$this->url($a);$this->getJson($url)->assertUnauthorized();$other=User::factory()->create();$this->actingAs($other,'sanctum')->getJson($url)->assertNotFound();$this->actingAs($u,'sanctum')->getJson($url)->assertOk()->assertJsonPath('data.status','insufficient_data')->assertJsonPath('data.audited_rows',0);$this->getJson('/api/v1/ad-accounts/'.$a->id.'/canonical-integrity?start_date=2026-02-30&end_date=2026-11-01')->assertUnprocessable();$this->getJson('/api/v1/ad-accounts/'.$a->id.'/canonical-integrity?start_date=2020-01-01&end_date=2026-11-01')->assertUnprocessable();}
 public function test_legacy_is_not_verified_and_read_does_not_repair_rows():void{[$u,$a,$c]=$this->fixture();$m=$this->metric($a,$c);$before=$m->fresh()->getAttributes();$this->actingAs($u,'sanctum')->getJson($this->url($a))->assertJsonPath('data.status','structurally_consistent_unverified_lineage')->assertJsonPath('data.provider_verified',false)->assertJsonPath('data.blocking_rows',0)->assertJsonPath('data.lineage.legacy_or_unverified',1)->assertJsonPath('data.historical_repair_performed',false);$this->assertSame($before,$m->fresh()->getAttributes());}
 public function test_foreign_parent_and_duplicate_scope_are_blocking_not_silently_repaired():void{[$u,$a,$c]=$this->fixture();[$ou,$oa,$oc]=$this->fixture();$this->metric($a,$oc);$this->metric($a,$oc,['provider'=>'google']);$this->actingAs($u,'sanctum')->getJson($this->url($a))->assertOk()->assertJsonPath('data.status','integrity_issues')->assertJsonPath('data.blocking_rows',2)->assertJsonPath('data.issue_counts.campaign_parent_mismatch',2)->assertJsonPath('data.issue_counts.duplicate_canonical_entity_day',1);$this->assertSame(2,PerformanceMetric::where('connected_ad_account_id',$a->id)->count());}
 public function test_strict_recorded_lineage_requires_owned_successful_run_and_payload():void{[$u,$a,$c]=$this->fixture();$run=SyncRun::create(['connected_ad_account_id'=>$a->id,'sync_type'=>'manual','status'=>'completed','started_at'=>now(),'completed_at'=>now()]);$raw=RawProviderPayload::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','endpoint'=>'fixture-insights','payload'=>[]]);$metadata=['canonical_resolution_version'=>'strict-parent-1','sync_run_id'=>$run->id,'raw_provider_payload_id'=>$raw->id,'provider_endpoint'=>'fixture-insights','synced_at'=>now()->toIso8601String(),'source_external_entity_ids'=>['external_campaign_id'=>$c->external_campaign_id],'entity_level'=>'campaign'];$m=$this->metric($a,$c,['metadata'=>$metadata]);$this->actingAs($u,'sanctum')->getJson($this->url($a))->assertJsonPath('data.status','structurally_consistent_recorded_lineage')->assertJsonPath('data.lineage.strict_recorded',1)->assertJsonPath('data.provider_verified',false);$changed=$metadata;$changed['source_external_entity_ids']=['external_campaign_id'=>'missing'];$m->update(['metadata'=>$changed]);$this->getJson($this->url($a))->assertJsonPath('data.issue_counts.strict_source_resolution_mismatch',1);$m->update(['metadata'=>$metadata]);$run->update(['status'=>'failed']);$this->getJson($this->url($a))->assertJsonPath('data.status','integrity_issues')->assertJsonPath('data.lineage.invalid_reference',1);}
}
